def find_path(graph, start, goal):
    # If the start and goal are the same, we have a trivial path
    if start == goal:
        return [start]

    # Initialize the stack for DFS and a set to track visited nodes
    stack = [(start, [start])]  # Each tuple contains (current node, path list)
    visited = set()

    while stack:
        (current_node, path) = stack.pop()
        if current_node not in visited:
            visited.add(current_node)
            # If the current node is the goal, we found the path
            if current_node == goal:
                return path
            # Explore neighbors
            for neighbor in graph.get(current_node, []):
                if neighbor not in visited:
                    stack.append((neighbor, path + [neighbor]))
    # Return None if the goal is unreachable
    return None
