def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Initialize the stack for the recursive search
    def dfs(stack, path, visited):
        if stack == [] or (stack[-1] == goal and path[-1] != goal):
            return None

        node = stack.pop()
        path.append(node)

        if node == goal:
            return path

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                dfs(stack + [neighbor], path[:], visited)

        return dfs(stack, path, visited)

    visited = set()
    return dfs([start], [start], visited)

