def find_path(graph, start, goal):
    if start not in graph or goal not in graph:
        return None

    # Track visited nodes
    visited = set()

    # Use a stack for the recursive approach
    def dfs(start, goal, visited):
        if start == goal:
            return [start]
        visited.add(start)
        for neighbor in graph[start]:
            if neighbor not in visited:
                path = dfs(neighbor, goal, visited)
                if path:
                    return [start] + path

    result = dfs(start, goal, visited)
    return result if result else None
